// Custom FX — DSP (Rune). describe() declares the effect and its params;
// the same ids are used here (param / p.<id>) and in the UI (ui.knob('<id>')).

pub fn describe() {
  Fx::new("Warm Drive")
    .knob("drive", 0.0, 24.0, 6.0).unit("dB")
    .knob("tone", 200.0, 8000.0, 2000.0).unit("Hz")
}

pub fn new(sr, max_frames) {
  let shaper = Shaper::new();
  shaper.set_curve("tanh");
  #{ shaper: shaper, lp: [Biquad::new(sr), Biquad::new(sr)], buf: Sig::new(max_frames), sr: sr }
}

pub fn param(state, id, value) {
  if id == "drive" { state.shaper.set_drive(db_to_gain(value)); }
  if id == "tone" { for lp in state.lp { lp.set("lowpass", value, 0.7, 0.0); } }
}

pub fn process(state, io, p) {
  let ch = 0;
  while ch < io.outputs() && ch < 2 {
    io.read(ch, state.buf);
    state.shaper.process(state.buf);
    state.lp[ch].process(state.buf);
    state.buf.gain(1.0 / (1.0 + p.drive / 24.0));
    io.write(ch, state.buf);
    ch += 1;
  }
}

