// Custom FX — UI. ui.knob(id) binds a knob to the param declared in DSP;
// ui.auto() renders every declared param. Top-level code is the render body
// (re-run on every update) with root, h, ui, logic, values in scope.

root.append(
  h('div', { class: 'row' }, ui.knob('drive'), ui.knob('tone')),
);
